     end

     if (sequencer == null && m_parent_sequence != null) begin
       sequencer = m_parent_sequence.get_sequencer();
     end

     set_sequencer(sequencer); 
     if (m_parent_sequence != null) begin
       set_depth(m_parent_sequence.get_depth() + 1);
     end

     reseed();      
  endfunction


